// Parse and validate the model's JSON. Never trust it structurally.
//
// response_format: json_object makes well-formed JSON very likely, not certain,
// and it says nothing about whether the KEYS are right. Models drop fields,
// invent categories, wrap output in code fences, and occasionally return prose
// when they decide the request was unusual. Any of those would otherwise route
// a real ticket into a nonexistent queue.
//
// Everything that fails validation falls through to category "other" with
// needs_review set. A human sees it; nothing is silently dropped.

const VALID_CATEGORIES = ['voice', 'network', 'infrastructure', 'other'];

const ticket = $('Normalize Ticket').first().json;

const fallback = (reason) => ({
  json: {
    ...ticket,
    category: 'other',
    confidence: 0,
    summary: `Automatic classification failed (${reason}). Subject: ${ticket.subject}`,
    first_diagnostic_step: 'Read the ticket manually — the classifier did not return usable output.',
    needs_review: true,
    classifier_error: reason,
  },
});

const results = [];

for (const item of $input.all()) {
  const content = item.json?.choices?.[0]?.message?.content;

  if (typeof content !== 'string' || content.trim() === '') {
    results.push(fallback('empty model response'));
    continue;
  }

  // Strip ```json fences if the model added them despite instructions.
  const cleaned = content
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (e) {
    results.push(fallback('malformed JSON: ' + e.message));
    continue;
  }

  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    results.push(fallback('model returned a non-object'));
    continue;
  }

  const category = String(parsed.category || '').toLowerCase().trim();
  if (!VALID_CATEGORIES.includes(category)) {
    results.push(fallback(`unknown category "${parsed.category}"`));
    continue;
  }

  const summary = String(parsed.summary || '').trim();
  if (summary === '') {
    results.push(fallback('missing summary'));
    continue;
  }

  let confidence = Number(parsed.confidence);
  if (!Number.isFinite(confidence)) confidence = 0.5;
  confidence = Math.max(0, Math.min(1, confidence));

  const firstStep = String(parsed.first_diagnostic_step || '').trim();

  results.push({
    json: {
      ...ticket,
      category,
      confidence,
      summary,
      first_diagnostic_step: firstStep || 'No first step suggested.',
      // Low-confidence classifications are routed normally but flagged, so the
      // queue owner knows to sanity-check before spending time on it.
      needs_review: confidence < 0.5,
      classifier_error: null,
    },
  });
}

return results;

// The LLM call itself failed (network, auth, rate limit, 5xx). The ticket still
// has to go somewhere, so it is routed to "other" for a human to pick up.

const ticket = $('Normalize Ticket').first().json;
const err = $input.first().json?.error?.message || 'LLM request failed';

return [
  {
    json: {
      ...ticket,
      category: 'other',
      confidence: 0,
      summary: `Classifier unreachable. Subject: ${ticket.subject}`,
      first_diagnostic_step: 'Read the ticket manually — the classifier could not be reached.',
      needs_review: true,
      classifier_error: err,
    },
  },
];
